ALTER TABLE public.camp_memories ADD COLUMN taken_on date, ADD COLUMN approximate_year integer, ADD COLUMN location text NOT NULL DEFAULT '', ADD COLUMN people text NOT NULL DEFAULT '', ADD COLUMN story text NOT NULL DEFAULT '', ADD COLUMN audio_path text;
ALTER TABLE public.camp_memories ADD CONSTRAINT memory_year_range CHECK (approximate_year BETWEEN 1800 AND 2200), ADD CONSTRAINT memory_date_choice CHECK (taken_on IS NULL OR approximate_year IS NULL), ADD CONSTRAINT memory_context_lengths CHECK (char_length(location) <= 200 AND char_length(people) <= 500 AND char_length(story) <= 5000);
CREATE FUNCTION public.validate_memory_audio() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.audio_path IS NOT NULL AND NOT EXISTS (SELECT 1 FROM storage.objects WHERE bucket_id = 'camp-audio' AND name = NEW.audio_path) THEN RAISE EXCEPTION 'Audio must be uploaded first'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER validate_memory_audio BEFORE INSERT OR UPDATE ON public.camp_memories FOR EACH ROW EXECUTE FUNCTION public.validate_memory_audio();
CREATE POLICY "Visitors can upload memory audio" ON storage.objects FOR INSERT TO anon, authenticated WITH CHECK (bucket_id = 'camp-audio' AND name ~ '^[0-9a-f-]{36}\.(webm|ogg|mp4|mp3|wav|m4a)$' AND ((metadata->>'mimetype') IS NULL OR (metadata->>'mimetype') IN ('audio/webm','audio/ogg','audio/mp4','audio/mpeg','audio/wav','audio/x-wav','audio/x-m4a')) AND ((metadata->>'size') IS NULL OR (metadata->>'size')::bigint BETWEEN 1 AND 10485760));
CREATE POLICY "Visitors can listen to memory audio" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'camp-audio');
CREATE TABLE public.memory_comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), photo_key text NOT NULL, author text NOT NULL DEFAULT 'Un proche', body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT comment_lengths CHECK (char_length(author) BETWEEN 1 AND 80 AND char_length(btrim(body)) BETWEEN 1 AND 1000));
GRANT SELECT, INSERT ON public.memory_comments TO anon, authenticated;
GRANT ALL ON public.memory_comments TO service_role;
ALTER TABLE public.memory_comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Everyone can read memory comments" ON public.memory_comments FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Visitors can leave a kind word" ON public.memory_comments FOR INSERT TO anon, authenticated WITH CHECK (photo_key IN ('famille','p1','p2','p3','p4','p5','p6','p7','p8') OR EXISTS (SELECT 1 FROM public.camp_memories WHERE image_path = photo_key));
CREATE TABLE public.memory_reactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), photo_key text NOT NULL, kind text NOT NULL CHECK (kind IN ('like','heart')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.memory_reactions TO anon, authenticated;
GRANT ALL ON public.memory_reactions TO service_role;
ALTER TABLE public.memory_reactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Everyone can read memory reactions" ON public.memory_reactions FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Visitors can react to memories" ON public.memory_reactions FOR INSERT TO anon, authenticated WITH CHECK (photo_key IN ('famille','p1','p2','p3','p4','p5','p6','p7','p8') OR EXISTS (SELECT 1 FROM public.camp_memories WHERE image_path = photo_key));
CREATE INDEX memory_comments_photo ON public.memory_comments(photo_key, created_at);
CREATE INDEX memory_reactions_photo ON public.memory_reactions(photo_key, kind);